def finish_parse(self, last_lineno_seen):
        """Clean-up/summary tasks run at the end of parsing."""
        # If we were parsing a multi-line comment, we need to
        # "finish" it here.
        if self.comment_stack:
            self.handle_comment_end(last_lineno_seen)
        # We need to finish parsing the last line of the file.
        if self.line_stack:
            self.handle_line(self.line_stack.pop())
